-- 005 — júri com rubrica e certificado verificável (spec 033 US5, US6,
-- FR-006, FR-007). Notas ficam por critério; o ranking é calculado na hora
-- (média ponderada), então mudar peso recalcula sem tocar em nota. Resultado
-- só existe pro público depois de jury_results; certificados têm código
-- curto não sequencial, que é o link público de verificação.

CREATE TABLE rubric_criteria (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "hackathonId" TEXT NOT NULL REFERENCES hackathons("id"),
  "label" TEXT NOT NULL,
  "weight" INTEGER NOT NULL CHECK ("weight" BETWEEN 1 AND 1000),
  "position" INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX idx_rubric_criteria_hackathon ON rubric_criteria ("hackathonId", "position");

CREATE TABLE judge_assignments (
  "hackathonId" TEXT NOT NULL REFERENCES hackathons("id"),
  "judgeMemberId" INTEGER NOT NULL REFERENCES members("id"),
  "teamId" INTEGER NOT NULL REFERENCES teams("id") ON DELETE CASCADE,
  "createdAt" TEXT NOT NULL DEFAULT sqlite_now(),
  PRIMARY KEY ("hackathonId", "judgeMemberId", "teamId")
);
CREATE INDEX idx_judge_assignments_team ON judge_assignments ("teamId");

CREATE TABLE scores (
  "judgeMemberId" INTEGER NOT NULL REFERENCES members("id"),
  "teamId" INTEGER NOT NULL REFERENCES teams("id") ON DELETE CASCADE,
  "criterionId" INTEGER NOT NULL REFERENCES rubric_criteria("id") ON DELETE CASCADE,
  "score" INTEGER NOT NULL CHECK ("score" BETWEEN 1 AND 5),
  "comment" TEXT,
  "updatedAt" TEXT NOT NULL DEFAULT sqlite_now(),
  UNIQUE ("judgeMemberId", "teamId", "criterionId")
);
CREATE INDEX idx_scores_team ON scores ("teamId");

CREATE TABLE jury_results (
  "hackathonId" TEXT PRIMARY KEY REFERENCES hackathons("id"),
  "publishedAt" TEXT NOT NULL DEFAULT sqlite_now(),
  "publishedBy" INTEGER REFERENCES members("id")
);

CREATE TABLE certificates (
  "code" TEXT PRIMARY KEY,
  "memberId" INTEGER NOT NULL REFERENCES members("id"),
  "hackathonId" TEXT NOT NULL REFERENCES hackathons("id"),
  "kind" TEXT NOT NULL CHECK ("kind" IN ('participacao','mentoria','jurado','organizacao','premiacao')),
  "detail" TEXT,
  "issuedAt" TEXT NOT NULL DEFAULT sqlite_now(),
  UNIQUE ("memberId", "hackathonId", "kind")
);
CREATE INDEX idx_certificates_hackathon ON certificates ("hackathonId");
